def solve(g):
    h,w=len(g),len(g[0])
    noise=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]!=g[h-1-i][w-1-j]: noise.add(g[i][j])
    res=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j] in noise:
                for a,b in ((i,w-1-j),(h-1-i,j),(h-1-i,w-1-j)):
                    if g[a][b] not in noise: res[i][j]=g[a][b]; break
    return res
